mapper.sql:
WHERE requester_id = #{requesterId}
AND export_type = #{exportType}
AND status = #{status}

mapper.select:
SELECT  FROM sys_export_job

ORDER BY requested_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE sys_export_job
SET total_rows = #{totalRows}, processed_rows = #{processedRows},
    version_no = version_no + 1, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND status = 'EXPORTING' AND version_no = #{expectedVersion}
  AND #{totalRows} >= 0 AND #{processedRows} >= processed_rows
  AND #{processedRows} <= #{totalRows}
